def run(self, image, predictions):
    import numpy as np
    import cv2
    import math

    det = predictions
    img = image.numpy_image if hasattr(image, 'numpy_image') else image
    if img is None:
        return {'predictions': det, 'team_a_predictions': det, 'team_b_predictions': det, 'ball_predictions': det, 'ball_position': {}, 'ball_velocity': {'primary': None, 'balls': []}, 'player_velocities': [], 'player_numbers': [], 'camera_angle': {'error': 'no image'}, 'player_count': 0, 'ball_count': 0}

    h, w = img.shape[:2]
    xyxy = det.xyxy if hasattr(det, 'xyxy') else np.zeros((0, 4), dtype=float)
    n = len(xyxy)
    data = dict(det.data) if hasattr(det, 'data') and det.data is not None else {}

    def get_list(keys, default=None):
        for k in keys:
            v = data.get(k)
            try:
                if v is not None and len(v) == n:
                    return list(v)
            except Exception:
                pass
        return [default] * n

    class_names = get_list(['class_name', 'class'], 'object')
    confidences = det.confidence if hasattr(det, 'confidence') and det.confidence is not None else np.ones((n,), dtype=float)
    tracker_raw = getattr(det, 'tracker_id', None)
    tracker_ids = list(tracker_raw) if tracker_raw is not None else get_list(['tracker_id'], None)
    native_smoothed_speed = get_list(['smoothed_speed'], None)
    native_speed = get_list(['speed'], None)

    def base_class(v):
        s = str(v).lower().strip()
        if s.startswith('p') and ':' in s:
            return 'person'
        if s.startswith('ball'):
            return 'sports ball'
        return s

    base = [base_class(c) for c in class_names]

    if len(img.shape) == 3 and img.shape[-1] == 3:
        gray = cv2.cvtColor(img, cv2.COLOR_RGB2GRAY)
        hsv = cv2.cvtColor(img, cv2.COLOR_RGB2HSV)
    else:
        gray = cv2.cvtColor(img, cv2.COLOR_BGR2GRAY) if len(img.shape) == 3 else img
        hsv = cv2.cvtColor(img, cv2.COLOR_BGR2HSV) if len(img.shape) == 3 else cv2.cvtColor(cv2.cvtColor(img, cv2.COLOR_GRAY2BGR), cv2.COLOR_BGR2HSV)

    green = cv2.inRange(hsv, np.array([30, 30, 30]), np.array([98, 255, 255]))
    green = cv2.morphologyEx(green, cv2.MORPH_CLOSE, np.ones((9, 9), np.uint8))
    green = cv2.morphologyEx(green, cv2.MORPH_OPEN, np.ones((5, 5), np.uint8))
    green_d = cv2.dilate(green, np.ones((25, 25), np.uint8), iterations=1)

    def clip_box(box):
        x1, y1, x2, y2 = [int(round(float(v))) for v in box]
        return max(0, x1), max(0, y1), min(w - 1, x2), min(h - 1, y2)

    def iou(a, b):
        ax1, ay1, ax2, ay2 = [float(v) for v in a]
        bx1, by1, bx2, by2 = [float(v) for v in b]
        ix1, iy1, ix2, iy2 = max(ax1, bx1), max(ay1, by1), min(ax2, bx2), min(ay2, by2)
        inter = max(0.0, ix2 - ix1) * max(0.0, iy2 - iy1)
        aa = max(0.0, ax2 - ax1) * max(0.0, ay2 - ay1)
        bb = max(0.0, bx2 - bx1) * max(0.0, by2 - by1)
        return inter / max(aa + bb - inter, 1e-6)

    def center_dist(a, b):
        ax1, ay1, ax2, ay2 = [float(v) for v in a]
        bx1, by1, bx2, by2 = [float(v) for v in b]
        return math.hypot(((ax1 + ax2) - (bx1 + bx2)) / 2.0, ((ay1 + ay2) - (by1 + by2)) / 2.0)

    def player_on_pitch(box):
        x1, y1, x2, y2 = clip_box(box)
        bw, bh = max(1, x2 - x1), max(1, y2 - y1)
        cx = int((x1 + x2) / 2)
        foot_y = min(h - 1, int(y2))
        px1, px2 = max(0, int(x1 + 0.08 * bw)), min(w - 1, int(x2 - 0.08 * bw))
        py1, py2 = max(0, int(y2 - 0.08 * bh)), min(h - 1, int(y2 + 0.20 * bh))
        patch = green_d[py1:py2, px1:px2]
        foot_green = float((patch > 0).mean()) if patch.size else 0.0
        return bool(foot_green >= 0.08 or green_d[foot_y, max(0, min(w - 1, cx))] > 0)

    def ball_quality(box):
        x1, y1, x2, y2 = clip_box(box)
        bw, bh = max(1, x2 - x1), max(1, y2 - y1)
        cx, cy = int((x1 + x2) / 2), int((y1 + y2) / 2)
        aspect = bw / max(float(bh), 1.0)
        area_ratio = (bw * bh) / max(float(w * h), 1.0)
        pad = max(12, int(max(bw, bh) * 3.0))
        gp = green_d[max(0, cy - pad):min(h, cy + pad), max(0, cx - pad):min(w, cx + pad)]
        grass_ratio = float((gp > 0).mean()) if gp.size else 0.0
        return 0.0000003 <= area_ratio <= 0.02 and 0.30 <= aspect <= 3.0 and grass_ratio >= 0.01

    # De-duplicate objects coming from full-frame + sliced inference.
    candidates = []
    for i, cls in enumerate(base):
        if cls == 'person' and player_on_pitch(xyxy[i]):
            candidates.append(i)
        elif cls in ['sports ball', 'ball', 'soccer ball'] and ball_quality(xyxy[i]):
            candidates.append(i)

    ordered = sorted(candidates, key=lambda i: float(confidences[i]) if i < len(confidences) else 0.0, reverse=True)
    keep = []
    for i in ordered:
        duplicate = False
        for j in keep:
            if base[i] == base[j] and (iou(xyxy[i], xyxy[j]) > 0.50 or center_dist(xyxy[i], xyxy[j]) < 10.0):
                duplicate = True
                break
        if not duplicate:
            keep.append(i)
    keep = sorted(keep)

    try:
        det = det[keep]
    except Exception:
        pass

    xyxy = det.xyxy if hasattr(det, 'xyxy') else np.zeros((0, 4), dtype=float)
    class_names = [class_names[i] for i in keep] if keep else []
    base = [base[i] for i in keep] if keep else []
    tracker_ids = [tracker_ids[i] if i < len(tracker_ids) else None for i in keep] if keep else []
    native_smoothed_speed = [native_smoothed_speed[i] if i < len(native_smoothed_speed) else None for i in keep] if keep else []
    native_speed = [native_speed[i] if i < len(native_speed) else None for i in keep] if keep else []

    if not hasattr(self, '_player_number_by_tracker'):
        self._player_number_by_tracker = {}
        self._next_player_number = 1
    if not hasattr(self, '_prev_centers'):
        self._prev_centers = {}
    if not hasattr(self, '_prev_gray_small'):
        self._prev_gray_small = None
    if not hasattr(self, '_frame_counter'):
        self._frame_counter = 0
    if not hasattr(self, '_speed_ema'):
        self._speed_ema = {}

    def frame_time():
        md = getattr(image, 'video_metadata', None)
        if isinstance(md, dict):
            if md.get('frame_number') is not None and md.get('fps'):
                try:
                    return float(md['frame_number']) / max(float(md['fps']), 1e-6)
                except Exception:
                    pass
            for k in ['video_time_ms', 'frame_timestamp_ms', 'timestamp_ms']:
                if md.get(k) is not None:
                    try:
                        return float(md[k]) / 1000.0
                    except Exception:
                        pass
        self._frame_counter += 1
        return self._frame_counter / 30.0

    now = frame_time()
    px_per_meter = 55.0

    # Estimate global camera translation between frames. This is used to subtract panning/tilting motion.
    camera_dx_px, camera_dy_px, camera_response = 0.0, 0.0, 0.0
    try:
        small_w = 320
        scale = small_w / max(float(w), 1.0)
        small_h = max(1, int(h * scale))
        small = cv2.resize(gray, (small_w, small_h), interpolation=cv2.INTER_AREA).astype(np.float32)
        small = cv2.GaussianBlur(small, (5, 5), 0)
        if self._prev_gray_small is not None and self._prev_gray_small.shape == small.shape:
            (dx_s, dy_s), response = cv2.phaseCorrelate(self._prev_gray_small, small)
            dx, dy = float(dx_s) / max(scale, 1e-6), float(dy_s) / max(scale, 1e-6)
            if abs(dx) < 0.20 * w and abs(dy) < 0.20 * h:
                camera_dx_px = dx
                camera_dy_px = dy
                camera_response = float(response)
        self._prev_gray_small = small
    except Exception:
        pass

    def as_float(v):
        try:
            if v is None:
                return None
            if isinstance(v, (list, tuple, np.ndarray)):
                if len(v) == 0:
                    return None
                return float(np.linalg.norm(np.array(v, dtype=float)))
            return float(v)
        except Exception:
            return None

    def native_to_kmh(v):
        val = as_float(v)
        if val is None:
            return 0.0
        return val * 3.6 if val < 70.0 else val

    def tid_value(i):
        try:
            tid = tracker_ids[i]
            if tid is None:
                return None
            if isinstance(tid, float) and np.isnan(tid):
                return None
            return int(tid)
        except Exception:
            return None

    def smooth_speed(key, value, alpha=0.45, max_jump=18.0):
        prev = self._speed_ema.get(key)
        if prev is not None and value > prev + max_jump:
            value = prev + max_jump
        out = value if prev is None else alpha * value + (1.0 - alpha) * prev
        self._speed_ema[key] = out
        return out

    def camera_compensated_speed(i, prefix):
        x1, y1, x2, y2 = [float(v) for v in xyxy[i]]
        cx, cy = (x1 + x2) / 2.0, (y1 + y2) / 2.0
        tid = tid_value(i)
        key = f'{prefix}_{tid}' if tid is not None else f'{prefix}_pos_{int(cx/20)}_{int(cy/20)}'
        native_kmh = native_to_kmh(native_smoothed_speed[i] if i < len(native_smoothed_speed) else None)
        if native_kmh <= 0.0:
            native_kmh = native_to_kmh(native_speed[i] if i < len(native_speed) else None)

        corrected_kmh = native_kmh
        raw_kmh = native_kmh
        if key in self._prev_centers:
            prev = self._prev_centers[key]
            dt = max(now - prev.get('time', now - 1/30.0), 1/30.0)
            raw_dx = cx - prev.get('x', cx)
            raw_dy = cy - prev.get('y', cy)
            # Subtract the global camera motion from the apparent object motion.
            obj_dx = raw_dx - camera_dx_px
            obj_dy = raw_dy - camera_dy_px
            raw_kmh = (math.hypot(raw_dx, raw_dy) / dt / px_per_meter) * 3.6
            corrected_kmh = (math.hypot(obj_dx, obj_dy) / dt / px_per_meter) * 3.6
            # If phase correlation is weak, blend with Velocity block value instead of trusting the camera estimate fully.
            if camera_response < 0.08 and native_kmh > 0:
                corrected_kmh = 0.65 * corrected_kmh + 0.35 * native_kmh
        elif native_kmh > 0:
            corrected_kmh = native_kmh
            raw_kmh = native_kmh

        self._prev_centers[key] = {'x': cx, 'y': cy, 'time': now}
        corrected_kmh = smooth_speed(key, max(0.0, corrected_kmh), 0.40 if prefix == 'player' else 0.55, 10.0 if prefix == 'player' else 45.0)
        return corrected_kmh, raw_kmh, tid, key

    labels, player_numbers, player_velocities = [], [], []
    balls, ball_indices, ball_position = [], [], {}

    for i, cls in enumerate(base):
        if i >= len(xyxy):
            continue
        x1, y1, x2, y2 = [float(v) for v in xyxy[i]]
        cx, cy = (x1 + x2) / 2.0, (y1 + y2) / 2.0

        if cls == 'person':
            speed_kmh, raw_kmh, tid, key = camera_compensated_speed(i, 'player')
            if key not in self._player_number_by_tracker:
                self._player_number_by_tracker[key] = int(self._next_player_number)
                self._next_player_number += 1
            pno = self._player_number_by_tracker[key]
            speed_kmh = min(max(speed_kmh, 0.0), 38.0)
            raw_kmh = min(max(raw_kmh, 0.0), 60.0)
            label = f'P{pno} {int(round(speed_kmh))} km/h'
            labels.append(label)
            base_out = {'player_number': int(pno), 'tracker_id': tid, 'center_x': float(cx / max(w, 1)), 'center_y': float(cy / max(h, 1))}
            player_numbers.append(dict(base_out))
            vel = dict(base_out)
            vel.update({'estimated_speed_km_h': round(speed_kmh, 2), 'raw_uncompensated_speed_km_h': round(raw_kmh, 2), 'camera_motion_dx_px': round(camera_dx_px, 3), 'camera_motion_dy_px': round(camera_dy_px, 3), 'camera_motion_response': round(camera_response, 4), 'label': label, 'calibration': 'camera_compensated_pixels_per_meter_55', 'note': 'Vitesse affichée = déplacement objet moins translation globale caméra estimée. Pour précision pro: calibration terrain/homographie.'})
            player_velocities.append(vel)
        elif cls in ['sports ball', 'ball', 'soccer ball']:
            speed_kmh, raw_kmh, tid, key = camera_compensated_speed(i, 'ball')
            speed_kmh = min(max(speed_kmh, 0.0), 140.0)
            raw_kmh = min(max(raw_kmh, 0.0), 180.0)
            label = f'Ball {int(round(speed_kmh))} km/h'
            labels.append(label)
            ball_indices.append(i)
            b = {'tracker_id': tid, 'center_x': float(cx / max(w, 1)), 'center_y': float(cy / max(h, 1)), 'estimated_speed_km_h': round(speed_kmh, 2), 'raw_uncompensated_speed_km_h': round(raw_kmh, 2), 'camera_motion_dx_px': round(camera_dx_px, 3), 'camera_motion_dy_px': round(camera_dy_px, 3), 'camera_motion_response': round(camera_response, 4), 'label': label, 'bbox_xyxy': [float(v) for v in xyxy[i]]}
            balls.append(b)
            ball_position = {k: v for k, v in b.items() if k not in ['estimated_speed_km_h', 'raw_uncompensated_speed_km_h']}
        else:
            labels.append(str(class_names[i]) if i < len(class_names) else 'object')

    out_data = dict(det.data) if hasattr(det, 'data') and det.data is not None else {}
    out_data['class_name'] = np.array(labels)
    out_data['class'] = np.array(labels)
    out_data['label'] = np.array(labels)
    out_data['detection_id'] = np.array([f'soccer_{i}' for i in range(len(labels))])
    det.data = out_data

    def slice_det(indices):
        try:
            return det[indices]
        except Exception:
            return det

    camera_angle = {'method': 'phase_correlation_camera_motion_compensation', 'camera_motion': {'dx_px': round(camera_dx_px, 3), 'dy_px': round(camera_dy_px, 3), 'response': round(camera_response, 4)}, 'note': 'Les labels utilisent maintenant la vitesse corrigée du mouvement caméra. Zoom/rotation forte nécessitent une homographie terrain.'}
    ball_velocity = {'primary': max(balls, key=lambda x: x.get('estimated_speed_km_h', 0), default=None), 'balls': balls, 'calibration': 'camera_compensated_pixels_per_meter_55'}

    return {'predictions': det, 'team_a_predictions': det, 'team_b_predictions': slice_det([]), 'ball_predictions': slice_det(ball_indices), 'ball_position': ball_position, 'ball_velocity': ball_velocity, 'player_velocities': player_velocities, 'player_numbers': player_numbers, 'camera_angle': camera_angle, 'player_count': len(player_numbers), 'ball_count': len(balls)}
